#include <iostream>
#include <vector>
#include <queue>
#include <climits>
#include <cstring>
#include <algorithm>
using namespace std;

using ll = long long;
using PII = pair<int, int>;

struct Edge {
    int dest;
    ll cap;
    ll flow;
    int rev;
    Edge(int d, ll c, int r) : dest(d), cap(c), flow(0), rev(r) {}
};

class FlowNetwork {
public:
    int V, s, t;
    vector<vector<Edge>> adj;
    vector<int> dist, work;

    FlowNetwork(int nodes, int src, int dst) : V(nodes), s(src), t(dst) {
        adj.resize(V);
        dist.resize(V);
        work.resize(V);
    }

    void addEdge(int u, int v, ll capacity) {
        adj[u].emplace_back(v, capacity, adj[v].size());
        adj[v].emplace_back(u, 0, adj[u].size() - 1);
    }

    bool bfs() {
        fill(dist.begin(), dist.end(), -1);
        queue<int> q;
        dist[s] = 0;
        q.push(s);
        while (!q.empty()) {
            int u = q.front(); q.pop();
            for (const auto& e : adj[u]) {
                if (e.cap - e.flow > 0 && dist[e.dest] == -1) {
                    dist[e.dest] = dist[u] + 1;
                    q.push(e.dest);
                }
            }
        }
        return dist[t] != -1;
    }

    ll dfs(int u, ll flow) {
        if (u == t) return flow;
        for (int& i = work[u]; i < (int)adj[u].size(); ++i) {
            Edge& e = adj[u][i];
            if (dist[e.dest] == dist[u] + 1 && e.cap - e.flow > 0) {
                ll pushed = dfs(e.dest, min(flow, e.cap - e.flow));
                if (pushed > 0) {
                    e.flow += pushed;
                    adj[e.dest][e.rev].flow -= pushed;
                    return pushed;
                }
            }
        }
        return 0;
    }

    ll maxFlow() {
        ll result = 0;
        while (bfs()) {
            fill(work.begin(), work.end(), 0);
            while (ll pushed = dfs(s, LLONG_MAX)) {
                result += pushed;
            }
        }
        return result;
    }
};

int fireTime[150][150], reachTime[150][150];
int idMap[150][150];
int N, Tlimit;
vector<string> mapGrid, capGrid;

vector<PII> getAdj(int r, int c) {
    vector<PII> res;
    if (r + 1 < N) res.push_back({r+1, c});
    if (r - 1 >= 0) res.push_back({r-1, c});
    if (c + 1 < N) res.push_back({r, c+1});
    if (c - 1 >= 0) res.push_back({r, c-1});
    return res;
}

void fireSpread(int sr, int sc) {
    memset(fireTime, -1, sizeof(fireTime));
    queue<PII> q;
    fireTime[sr][sc] = 0;
    q.push({sr, sc});
    while (!q.empty()) {
        auto [r, c] = q.front(); q.pop();
        for (auto [nr, nc] : getAdj(r, c)) {
            char ch = mapGrid[nr][nc];
            if ((ch != 'Z' && !isdigit(ch)) || fireTime[nr][nc] != -1) continue;
            fireTime[nr][nc] = fireTime[r][c] + 1;
            q.push({nr, nc});
        }
    }
    for (int i = 0; i < N; ++i)
        for (int j = 0; j < N; ++j)
            if (isdigit(mapGrid[i][j]) && fireTime[i][j] == -1)
                fireTime[i][j] = Tlimit;
}

void reachSpread(int sr, int sc) {
    memset(reachTime, -1, sizeof(reachTime));
    queue<PII> q;
    reachTime[sr][sc] = 0;
    q.push({sr, sc});
    while (!q.empty()) {
        auto [r, c] = q.front(); q.pop();
        for (auto [nr, nc] : getAdj(r, c)) {
            if (!isdigit(mapGrid[nr][nc]) || reachTime[nr][nc] != -1) continue;
            reachTime[nr][nc] = reachTime[r][c] + 1;
            q.push({nr, nc});
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> N >> Tlimit;
    mapGrid.resize(N);
    capGrid.resize(N);
    for (int i = 0; i < N; ++i) cin >> mapGrid[i];
    for (int i = 0; i < N; ++i) cin >> capGrid[i];

    int fireR = -1, fireC = -1;
    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            idMap[i][j] = i * N + j + 1;
            if (mapGrid[i][j] == 'Z') {
                fireR = i;
                fireC = j;
            }
        }
    }

    fireSpread(fireR, fireC);

    int totalNodes = 2 * N * N + 2;
    FlowNetwork network(totalNodes, 0, totalNodes - 1);

    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            if (isdigit(mapGrid[i][j])) {
                int people = mapGrid[i][j] - '0';
                network.addEdge(0, idMap[i][j], people);
                reachSpread(i, j);
                for (int r = 0; r < N; ++r) {
                    for (int c = 0; c < N; ++c) {
                        if (isdigit(capGrid[r][c]) && reachTime[r][c] != -1 &&
                            reachTime[r][c] <= fireTime[r][c] && reachTime[r][c] <= Tlimit) {
                            bool valid = true;
                            if (reachTime[r][c] == fireTime[r][c]) {
                                valid = false;
                                for (auto [nr, nc] : getAdj(r, c)) {
                                    if (reachTime[nr][nc] != -1 &&
                                        reachTime[nr][nc] < fireTime[nr][nc]) {
                                        valid = true;
                                        break;
                                    }
                                }
                            }
                            if (valid) {
                                network.addEdge(idMap[i][j], N * N + idMap[r][c], people);
                            }
                        }
                    }
                }
            }
        }
    }

    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            if (isdigit(capGrid[i][j])) {
                int cap = capGrid[i][j] - '0';
                network.addEdge(N * N + idMap[i][j], totalNodes - 1, cap);
            }
        }
    }

    cout << network.maxFlow() << '\n';
}
